/**
 * Generated by ownmcp. Review every tool before shipping it.
 * Declared owner origin: http://127.0.0.1:44731
 * Inputs: demo/openapi.json, demo/shop.html, test/fixtures/pantry.har
 *
 * State-changing tools call requireConfirmation() and do not send the request
 * unless confirm() returns true. consequentialHint asks a WebMCP client to
 * prompt; the 13 November 2026 draft does not enforce that prompt itself.
 * This milestone sets consequentialHint on every mutation. Clear it for a
 * reversible action if you want a quieter agent.
 */
import { fillPath, ownerUrl, registerOwnedTools, requireConfirmation } from "ownmcp";
import type { ConfirmFn, ModelContextLike, WebMcpTool } from "ownmcp";

export interface PantryOptions {
  baseUrl: string;
  confirm?: ConfirmFn;
}

export function createPantryTools(options: PantryOptions): WebMcpTool[] {
  return [
    {
      name: "add_to_cart",
      title: "Add a shelf item to the basket",
      description: "Add a shelf item to the basket. State-changing: the handler does not call the app unless confirm() returns true. The result is { ok, status, body }.",
      inputSchema: {
          "type": "object",
          "properties": {
            "sku": {
              "type": "string",
              "description": "Shelf sku.",
              "enum": [
                "coffee",
                "tea",
                "honey"
              ]
            },
            "qty": {
              "type": "integer",
              "description": "How many to add.",
              "minimum": 1,
              "maximum": 12
            }
          },
          "required": [
            "sku",
            "qty"
          ]
        },
      annotations: {
        readOnlyHint: false,
        untrustedContentHint: false,
        consequentialHint: true,
        debugging: false,
      },
      async execute(input: Record<string, unknown>, agent?: { signal?: AbortSignal }) {
        await requireConfirmation("state-changing", "add_to_cart", input, options.confirm);
        const url = ownerUrl(options.baseUrl, fillPath("/api/cart", input));
        const response = await fetch(url, {
          headers: { accept: "application/json", "content-type": "application/json" },
          method: "POST",
          signal: agent?.signal,
          body: JSON.stringify({ "sku": input["sku"], "qty": input["qty"] }),
        });
        return readResponse(response);
      },
    },
    {
      name: "get_cart",
      title: "Read the current basket and its total",
      description: "Read the current basket and its total. Read-only: it does not change app state. The result is { ok, status, body }.",
      inputSchema: {
          "type": "object",
          "properties": {}
        },
      annotations: {
        readOnlyHint: true,
        untrustedContentHint: false,
        consequentialHint: false,
        debugging: false,
      },
      async execute(input: Record<string, unknown>, agent?: { signal?: AbortSignal }) {
        const url = ownerUrl(options.baseUrl, fillPath("/api/cart", input));
        const response = await fetch(url, {
          headers: { accept: "application/json" },
          method: "GET",
          signal: agent?.signal,
        });
        return readResponse(response);
      },
    },
    {
      name: "list_orders",
      title: "List orders placed during this server process",
      description: "List orders placed during this server process. Read-only: it does not change app state. The result is { ok, status, body }.",
      inputSchema: {
          "type": "object",
          "properties": {}
        },
      annotations: {
        readOnlyHint: true,
        untrustedContentHint: false,
        consequentialHint: false,
        debugging: false,
      },
      async execute(input: Record<string, unknown>, agent?: { signal?: AbortSignal }) {
        const url = ownerUrl(options.baseUrl, fillPath("/api/orders", input));
        const response = await fetch(url, {
          headers: { accept: "application/json" },
          method: "GET",
          signal: agent?.signal,
        });
        return readResponse(response);
      },
    },
    {
      name: "list_products",
      title: "List the jars, tins, and bags currently on the shelf",
      description: "List the jars, tins, and bags currently on the shelf. Read-only: it does not change app state. The result is { ok, status, body }.",
      inputSchema: {
          "type": "object",
          "properties": {}
        },
      annotations: {
        readOnlyHint: true,
        untrustedContentHint: false,
        consequentialHint: false,
        debugging: false,
      },
      async execute(input: Record<string, unknown>, agent?: { signal?: AbortSignal }) {
        const url = ownerUrl(options.baseUrl, fillPath("/api/products", input));
        const response = await fetch(url, {
          headers: { accept: "application/json" },
          method: "GET",
          signal: agent?.signal,
        });
        return readResponse(response);
      },
    },
    {
      name: "place_order",
      title: "Place an in-memory order for the current basket and clear it",
      description: "Place an in-memory order for the current basket and clear it. This demo does not charge a card. State-changing: the handler does not call the app unless confirm() returns true. The result is { ok, status, body }.",
      inputSchema: {
          "type": "object",
          "properties": {}
        },
      annotations: {
        readOnlyHint: false,
        untrustedContentHint: false,
        consequentialHint: true,
        debugging: false,
      },
      async execute(input: Record<string, unknown>, agent?: { signal?: AbortSignal }) {
        await requireConfirmation("state-changing", "place_order", input, options.confirm);
        const url = ownerUrl(options.baseUrl, fillPath("/api/checkout", input));
        const response = await fetch(url, {
          headers: { accept: "application/json" },
          method: "POST",
          signal: agent?.signal,
        });
        return readResponse(response);
      },
    }
  ];
}

export async function registerPantryTools(
  options: PantryOptions & { context?: ModelContextLike; signal?: AbortSignal },
): Promise<ModelContextLike> {
  return registerOwnedTools(createPantryTools(options), {
    context: options.context,
    signal: options.signal,
  });
}

async function readResponse(response: Response): Promise<{ ok: boolean; status: number; body: unknown }> {
  const text = await response.text();
  let body: unknown = text;
  if (text) {
    try {
      body = JSON.parse(text) as unknown;
    } catch {
      // The app answered with text. Keep it on body.
    }
  } else {
    body = null;
  }
  return { ok: response.ok, status: response.status, body };
}
